import{_ as i,C as a,o as d,c,j as t,a as o,E as r,ag as l}from"./chunks/framework.HG0H2VLS.js";const q=JSON.parse('{"title":"NumericAnswers","description":"","frontmatter":{},"headers":[],"relativePath":"cc-patterns/numeric-answers.md","filePath":"cc-patterns/numeric-answers.md"}'),h={name:"cc-patterns/numeric-answers.md"},u={id:"numericanswers",tabindex:"-1"};function p(m,e,g,w,f,b){const n=a("Badge"),s=a("ComponentDemo");return d(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-numericanswers",tabindex:"-1"},[o("title: NumericAnswers "),t("a",{class:"header-anchor",href:"#title-numericanswers","aria-label":'Permalink to "title: NumericAnswers"'},"​")],-1)),t("h1",u,[e[0]||(e[0]=o("NumericAnswers ",-1)),r(n,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#numericanswers","aria-label":'Permalink to "NumericAnswers <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,`AI Profile's metric layer as the "Numeric Data" section: Numeric Data Answers switch, Mapping status (Badge + who/when), notices (Alert: not rebuilt / older than prompt / blocking problems / Check: advisories), Generation Prompt with "Use standard wording", and the column readings in a closed Accordion + Table ("Needs a look" first)`)],-1)),r(s,{src:"/demos/src/cc/patterns/NumericAnswers/NumericAnswers.html"}),e[6]||(e[6]=l('<h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>AI Profile&#39;s <strong>metric layer</strong> (v1 <code>AfcAI/CC/AIProfileMetricLayerInclude.cfm</code>, TASK-354014 and TASK-390334). It tells the AI engine which spreadsheet column is a measure and which is a dimension, so numeric questions are answered by calculation rather than by the model reading numbers out of prose.</p><p>Since Markus&#39;s steer (21 Aug) there&#39;s <strong>no JSON and there are no Generate / Apply buttons</strong>. Saving the profile works the mapping out, and saving is the operator&#39;s confirmation. Apart from the switch and the prompt, the panel is a read-only explanation of what the save did. v3 keeps that model exactly.</p><h2 id="parts-mark-2026-10-29" tabindex="-1">Parts (Mark, 2026-10-29) <a class="header-anchor" href="#parts-mark-2026-10-29" aria-label="Permalink to &quot;Parts (Mark, 2026-10-29)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Kit pieces</th><th>v1 source</th></tr></thead><tbody><tr><td><strong>Numeric Data Answers</strong> switch</td><td>FieldRow Checkbox (View: On / Off)</td><td><code>TypedExtractionYN</code>, on by default, saved with the profile</td></tr><tr><td><strong>Mapping</strong> status</td><td>FieldRow (check-aligned) + Badge: Confirmed = success, Draft = warning, No mapping yet = neutral; then &quot;on {date} by {name} · numeric answering is live&quot;</td><td><code>EXISTS</code> / <code>CONFIRMED</code> / <code>CONFIRMEDDATE</code> / <code>CONFIRMEDBYNAME</code></td></tr><tr><td>Notices (only when needed)</td><td>Alert warning: &quot;The figures have not been rebuilt yet…&quot; (<code>STALE</code> + <code>LASTINDEX</code>) and &quot;This mapping is older than the prompt…&quot; (<code>PROMPTMOVED</code>). Alert danger &quot;This mapping can&#39;t be put into service yet.&quot; lists blocking <code>PROBLEMS</code>. Alert warning &quot;Worth checking…&quot; lists the <code>Check:</code> advisories (prefix stripped)</td><td>v1 drew blocking red, advisory amber</td></tr><tr><td><strong>Generation Prompt</strong></td><td>FieldRow Textarea, with a Badge &quot;Standard wording&quot; / &quot;Customised for this profile&quot; and <strong>Use standard wording</strong> (Tertiary sm, <code>rotate-ccw</code>, shown only while customised) above it. View: the text + Badge</td><td><code>PROMPT</code> / <code>PROMPTISDEFAULT</code>; v1&#39;s clear-to-reset</td></tr><tr><td><strong>How these spreadsheets are being read</strong></td><td>Accordion (default size), <strong>closed on load</strong>. The trigger shows the title + &quot;N spreadsheet columns · N understood&quot; + a warning Badge &quot;N need a look&quot;. Panel: Table (Column / Spreadsheet › Sheet / How it&#39;s read), &quot;Needs a look&quot; rows first with a warning Badge and the concern in <code>--ao-text-warning</code></td><td><code>COLUMNS</code> / <code>STATS</code>, wording per v1 <code>aoMLDescribe</code></td></tr><tr><td>Add (unsaved)</td><td>Note: &quot;The numeric data mapping can be set up once this profile has been saved.&quot;</td><td>v1, same</td></tr><tr><td>Nothing indexed</td><td>Note in the panel: &quot;No spreadsheet columns found…&quot;</td><td>v1, same</td></tr></tbody></table><p>The section is titled <strong>&quot;Numeric Data&quot;</strong>, so it doesn&#39;t repeat its first field&#39;s label.</p><h2 id="behaviour-numericanswers-js" tabindex="-1">Behaviour (NumericAnswers.js) <a class="header-anchor" href="#behaviour-numericanswers-js" aria-label="Permalink to &quot;Behaviour (NumericAnswers.js)&quot;">​</a></h2><ul><li>The Accordion toggles, with <code>aria-expanded</code> kept in step.</li><li>Prompt: the Badge and the reset follow whether the text equals <code>data-standard</code>. <strong>Use standard wording</strong> puts the standard text back and focuses the field. The backend should store an empty override when the text equals the standard (<code>ml-prompt</code>), so the profile keeps tracking future improvements.</li></ul><h2 id="backend-handover-→-recordscreen" tabindex="-1">Backend (HANDOVER → RecordScreen) <a class="header-anchor" href="#backend-handover-→-recordscreen" aria-label="Permalink to &quot;Backend (HANDOVER → RecordScreen)&quot;">​</a></h2><ul><li><code>ml-layer</code>: every value comes from <code>AIProfile.cfc getMetricLayerData</code>.</li><li><code>ml-prompt</code>: store an empty override when the text equals the standard wording.</li></ul><h2 id="verified-headless-chrome-2026-10-29" tabindex="-1">Verified (headless Chrome, 2026-10-29) <a class="header-anchor" href="#verified-headless-chrome-2026-10-29" aria-label="Permalink to &quot;Verified (headless Chrome, 2026-10-29)&quot;">​</a></h2><p>18 checks pass on AIProfileEdit / View and the demo:</p><ul><li>the section order; the switch; the Confirmed badge with who and when; both notices;</li><li>the accordion is closed on load with its summary and badge, and opens on click;</li><li>&quot;Needs a look&quot; rows come first;</li><li>the prompt Standard → Customised → reset cycle, and its focus;</li><li>View is read-only;</li><li>no overflow at 1280 or 480 (the table scrolls inside its wrap);</li><li>all five demo states render; no page errors.</li></ul><p>Screenshots were checked in light and dark.</p><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><p>All parts keep their own tokens. Pattern CSS adds only:</p><ul><li>gaps <code>--ao-spacing-2</code> (status, column title: = TopicTree badges) and <code>--ao-spacing-3</code> (notices, prompt column and bar: = EditGrid);</li><li>the meta text <code>--ao-text-secondary</code>; the concern <code>--ao-text-warning</code>;</li><li>the reading column wraps with <code>--ao-size-4</code> as its minimum width (Table cells are nowrap).</li></ul><h2 id="token-gaps" tabindex="-1">Token Gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token Gaps&quot;">​</a></h2><p>None.</p><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=4529-45811" target="_blank" rel="noreferrer">Open in Figma</a></p>',21))])}const A=i(h,[["render",p]]);export{q as __pageData,A as default};
